{"tool":"execute","arguments":{"code":"vendors = {v['id']: v for v in data['vendors']}
skus = sorted(data['skus'])
options = []
for sku in skus:
    spec = data['skus'][sku]
    options.append([q for q in data['quotes'] if q['sku'] == sku and spec['demand'] <= q['units'] <= spec['demand'] + 2 and q['arrival'] <= spec['deadline'] and q['quality'] == 'approved'])
best = None
best_ids = None
feasible = 0
for selection in itertools.product(*options):
    chosen = {q['sku']: q for q in selection}
    used = set(q['vendor'] for q in selection)
    if len(used) < 3 or sum(q['carbon'] for q in selection) > data['carbon_cap']:
        continue
    if any(q['needs_same_vendor_sku'] and chosen[q['needs_same_vendor_sku']]['vendor'] != q['vendor'] for q in selection):
        continue
    total = 0
    valid = True
    for vendor_id in used:
        v = vendors[vendor_id]
        lots = [q for q in selection if q['vendor'] == vendor_id]
        units = sum(q['units'] for q in lots)
        if units > v['unit_cap']:
            valid = False
            break
        gross = sum(q['units'] * q['unit_cents'] for q in lots)
        bps = v['tier_bps'] if units >= v['tier_units'] else 0
        merchandise = (gross * (10000 - bps) + 5000) // 10000
        total += merchandise
        if gross < v['free_shipping_gross']:
            total += v['shipping_cents']
        if len(set(q['sku'] for q in lots)) >= 2 and merchandise >= v['rebate_merchandise_min']:
            total -= v['rebate_cents']
    if valid:
        feasible += 1
        if best is None or total < best:
            best = total
            best_ids = [q['id'] for q in selection]
print({'minimum': best, 'quotes': best_ids, 'feasible_count': feasible, 'vendors': data['vendors']})"}}

